using System.Collections;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "GainEffectBasedOnAstriumAction", menuName = "Data/Battle/Battle Actions/Orion/GainEffectBasedOnAstrium Action")]
public class GainEffectBasedOnAstriumAction : BattleAction
{
	[Header("Gain Effect Based On Asrtium Action")]
	[SerializeField]
	private AstriumEffect astriumEffect;

	[SerializeField]
	private DefaultEffectAction gainAstriumAction;

	[SerializeField]
	private DefaultEffectAction gainEffectAction;

	[SerializeField]
	private float vfxDelay = 0.5f;

	[SerializeField]
	private StarAbility orbToCast;

	[SerializeField]
	private int orbCastAmount = 1;

	public DefaultEffectAction GainEffectAction => gainEffectAction;

	public StarAbility OrbToCast => orbToCast;

	public int OrbCastAmount => orbCastAmount;

	public int GetEffectAmount(bool description)
	{
		int num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveGetAmount(astriumEffect, activateFeedback: false);
		bool flag = false;
		if (description && num < 9)
		{
			flag = true;
		}
		return Mathf.CeilToInt((float)(num + (flag ? 1 : 0)) / 2f);
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled())
		{
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(CastTargetDelay(target, source));
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			DefaultCast(target, source);
		}
	}

	private IEnumerator CastTargetDelay(GameObject target, GameObject source)
	{
		SpawnVFX(GetVFXOwnerPosition(target), 3f);
		PlaySFX();
		yield return new WaitForSeconds(vfxDelay);
		DefaultCast(target, source);
	}

	private void DefaultCast(GameObject target, GameObject source)
	{
		if (target.GetComponent<UnitEffects>().IsEffectActiveGetAmount(astriumEffect, activateFeedback: false) < 9)
		{
			gainAstriumAction.CastTargetAmount(target, 1, source);
		}
		gainEffectAction.CastTargetAmount(target, GetEffectAmount(description: false), source);
		for (int i = 0; i < orbCastAmount; i++)
		{
			orbToCast.OnActivateStarAbility();
		}
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
	}
}
